{\"bbox\": [{\"coord\": [253, 110, 1210, 177], \"page_id\": 11}], \"content\": \"Treasury Survey of the Ownership of Securities Issued or Guaranteed by the United States, March 31, 1941\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [298, 195, 1168, 226], \"page_id\": 11}], \"content\": \"Covering the Holdings of Large Banks and Insurance Companies\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [170, 280, 1313, 802], \"page_id\": 11}], \"content\": \"On March 29, 1941, Secretary Morgenthau wrote to the larger banks and insurance companies asking them to report the par amount of each security issued or guaranteed by the Federal Government owned by them on March 31, 1941. This information was requested in order that the Treasury might obtain a comprehensive picture of the ownership of Government securities, with the view to conducting the defense financing program with the greatest facility. The replies to Secretary Morgenthau's letter have been tabulated and the following tables have been made up to present some of the more important data. It should be noted that the reported data do not cover all of the commercial and savings banks and insurance companies in the country. They do cover, however, institutions that account for about 95 percent of the amount of United States Government and Government-guaranteed securities held by all banks and insurance companies.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [295, 903, 1208, 964], \"page_id\": 11}], \"content\": \"Table I.- Summary of Ownership by Type of Security, by Call Classes, and by Tax-Exemption Provision\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [581, 982, 907, 1013], \"page_id\": 11}], \"content\": \"(Par value - in millions of dollars)\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [104, 1020, 1384, 1748], \"page_id\": 1