ith open('/app/resources/treasury_bulletin_1941_05.json', 'r') as f:\n    data = json.load(f)\n\nelements = data['document']['elements']\n\n# There are two tables - one on page 20-21 and one continued on page 21-22\n# Let's check element 183 (the second table)\ntable2_html = elements[183]['content']\n\n# Check for Defense in both tables\nimport re\ndefense1 = re.findall(r'Nat\\. Defense Series.*?\\d+', elements[178]['content'])\ndefense2 = re.findall(r'Nat\\. Defense Series.*?\\d+', table2_html)\n\nprint(\"Defense items in first table (element 178):\")\nfor d in defense1:\n    print(f\"  {d}\")\n\nprint(\"\\nDefense items in second table (element 183):\")\nfor d in defense2:\n    print(f\"  {d}\")\n\nprint(f\"\\nTotal tables checked: 2\")\nprint(\"All National Defense Series items found in the maturity schedule tables\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
